mapper.select:
SELECT p.id, p.email, p.phone, p.created_at
FROM person p
WHERE p.workspace_id = #{workspaceId}
  AND p.id > #{afterId}
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
ORDER BY p.id
LIMIT #{limit}

SELECT c.id, c.website, c.phone, c.created_at
FROM company c
WHERE c.workspace_id = #{workspaceId}
  AND c.id > #{afterId}
ORDER BY c.id
LIMIT #{limit}

SELECT pi.person_id AS record_id, p.name, pi.kind, pi.normalized_value FROM person_identity pi JOIN person p ON p.workspace_id = pi.workspace_id AND p.id = pi.person_id WHERE pi.workspace_id = #{workspaceId} AND pi.kind = #{kind} AND pi.superseded_at IS NULL AND p.suspended_at IS NULL AND p.provision_ceased_at IS NULL AND pi.normalized_value IN
#{normalizedValue}
ORDER BY pi.normalized_value, pi.person_id

SELECT ci.company_id AS record_id, c.name, ci.kind, ci.normalized_value
FROM company_identity ci
JOIN company c ON c.workspace_id = ci.workspace_id AND c.id = ci.company_id
WHERE ci.workspace_id = #{workspaceId}
  AND ci.kind = #{kind}
  AND ci.superseded_at IS NULL
  AND ci.normalized_value IN

    #{normalizedValue}

ORDER BY ci.normalized_value, ci.company_id

mapper.update:
UPDATE person_identity pi
JOIN person p
  ON p.workspace_id = pi.workspace_id
  AND p.id = pi.person_id
SET pi.superseded_at = #{supersededAt}
WHERE pi.workspace_id = #{workspaceId}
  AND pi.person_id = #{personId}
  AND pi.kind = 'email'
  AND pi.superseded_at IS NULL
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
  AND (
    (p.email IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(p.email AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND pi.normalized_value <> #{normalizedValue}

UPDATE person_identity pi
JOIN person p
  ON p.workspace_id = pi.workspace_id
  AND p.id = pi.person_id
SET pi.superseded_at = #{supersededAt}
WHERE pi.workspace_id = #{workspaceId}
  AND pi.person_id = #{personId}
  AND pi.kind = 'phone'
  AND pi.superseded_at IS NULL
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
  AND (
    (p.phone IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(p.phone AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND pi.normalized_value <> #{normalizedValue}

UPDATE company_identity ci
JOIN company c
  ON c.workspace_id = ci.workspace_id
  AND c.id = ci.company_id
SET ci.superseded_at = #{supersededAt}
WHERE ci.workspace_id = #{workspaceId}
  AND ci.company_id = #{companyId}
  AND ci.kind = 'domain'
  AND ci.superseded_at IS NULL
  AND (
    (c.website IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(c.website AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND ci.normalized_value <> #{normalizedValue}

UPDATE company_identity ci
JOIN company c
  ON c.workspace_id = ci.workspace_id
  AND c.id = ci.company_id
SET ci.superseded_at = #{supersededAt}
WHERE ci.workspace_id = #{workspaceId}
  AND ci.company_id = #{companyId}
  AND ci.kind = 'phone'
  AND ci.superseded_at IS NULL
  AND (
    (c.phone IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(c.phone AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND ci.normalized_value <> #{normalizedValue}
